CREATE TABLE IF NOT EXISTS admins (id serial PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text NOT NULL, name text NOT NULL DEFAULT 'Administrator', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS admin_sessions (token_hash text PRIMARY KEY, admin_id integer NOT NULL REFERENCES admins(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS category_groups (id serial PRIMARY KEY, name text UNIQUE NOT NULL, slug text UNIQUE NOT NULL, description text NOT NULL DEFAULT '', sort_order integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS categories (id serial PRIMARY KEY, name text UNIQUE NOT NULL, slug text UNIQUE NOT NULL, group_name text NOT NULL DEFAULT 'Nuts', group_id integer REFERENCES category_groups(id) ON DELETE RESTRICT, image text NOT NULL DEFAULT '', sort_order integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS products (id serial PRIMARY KEY, name text NOT NULL, slug text UNIQUE NOT NULL, category_id integer REFERENCES categories(id) ON DELETE RESTRICT, description text NOT NULL DEFAULT '', about_item text NOT NULL DEFAULT '', ingredients text NOT NULL DEFAULT '', storage text NOT NULL DEFAULT '', image text NOT NULL DEFAULT '', bestseller boolean NOT NULL DEFAULT false, featured boolean NOT NULL DEFAULT false, is_new boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS variants (id serial PRIMARY KEY, product_id integer NOT NULL REFERENCES products(id) ON DELETE CASCADE, weight text NOT NULL, price numeric(12,2) NOT NULL CHECK(price>=0), mrp numeric(12,2) NOT NULL CHECK(mrp>=price), stock integer NOT NULL DEFAULT 0 CHECK(stock>=0), weight_kg numeric(8,3) NOT NULL DEFAULT 0.5 CHECK(weight_kg>0), length_cm numeric(8,2) NOT NULL DEFAULT 20 CHECK(length_cm>0), breadth_cm numeric(8,2) NOT NULL DEFAULT 20 CHECK(breadth_cm>0), height_cm numeric(8,2) NOT NULL DEFAULT 10 CHECK(height_cm>0), UNIQUE(product_id,weight));
CREATE TABLE IF NOT EXISTS product_images (id serial PRIMARY KEY, product_id integer NOT NULL REFERENCES products(id) ON DELETE CASCADE, image text NOT NULL, alt text NOT NULL DEFAULT '', sort_order integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS customers (id serial PRIMARY KEY, name text NOT NULL DEFAULT '', phone text NOT NULL UNIQUE, email text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS addresses (id serial PRIMARY KEY, customer_id integer NOT NULL REFERENCES customers(id) ON DELETE CASCADE, address text NOT NULL, landmark text NOT NULL DEFAULT '', city text NOT NULL, state text NOT NULL, pincode text NOT NULL);
CREATE TABLE IF NOT EXISTS coupons (id serial PRIMARY KEY, code text UNIQUE NOT NULL, type text NOT NULL CHECK(type IN ('percent','fixed')), value numeric(12,2) NOT NULL CHECK(value>0 AND (type!='percent' OR value<=100)), min_cart numeric(12,2) NOT NULL DEFAULT 0 CHECK(min_cart>=0), label text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS orders (id serial PRIMARY KEY, order_number text UNIQUE NOT NULL, customer_id integer REFERENCES customers(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'Confirmed' CHECK(status IN ('Confirmed','Packed','Shipped','Out for Delivery','Delivered','Cancelled')), payment text NOT NULL DEFAULT 'cod' CHECK(payment IN ('cod','razorpay')), payment_status text NOT NULL DEFAULT 'Unpaid' CHECK(payment_status IN ('Unpaid','Paid','Refunded')), subtotal numeric(12,2) NOT NULL CHECK(subtotal>=0), discount numeric(12,2) NOT NULL DEFAULT 0 CHECK(discount>=0), shipping numeric(12,2) NOT NULL DEFAULT 0 CHECK(shipping>=0), total numeric(12,2) NOT NULL CHECK(total>=0), customer_snapshot jsonb NOT NULL, coupon_code text, tracking_number text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS order_items (id serial PRIMARY KEY, order_id integer NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id integer REFERENCES products(id) ON DELETE SET NULL, variant_id integer REFERENCES variants(id) ON DELETE SET NULL, product_name text NOT NULL, weight text NOT NULL, price numeric(12,2) NOT NULL CHECK(price>=0), quantity integer NOT NULL CHECK(quantity>0));
CREATE TABLE IF NOT EXISTS banners (id serial PRIMARY KEY, title text NOT NULL, subtitle text NOT NULL DEFAULT '', image text NOT NULL DEFAULT '', link text NOT NULL DEFAULT '/shop', button_text text NOT NULL DEFAULT 'Shop collection', placement text NOT NULL DEFAULT 'hero' CHECK(placement IN ('hero','seasonal','bottom','promotion')), active boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS pages (id serial PRIMARY KEY, slug text UNIQUE NOT NULL, title text NOT NULL, content text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS reviews (id serial PRIMARY KEY, product_id integer NOT NULL REFERENCES products(id) ON DELETE CASCADE, customer_name text NOT NULL, rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5), content text NOT NULL, approved boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS navigation (id serial PRIMARY KEY, label text NOT NULL, url text NOT NULL, location text NOT NULL DEFAULT 'footer' CHECK(location IN ('header','footer')), parent_id integer NOT NULL DEFAULT 0, menu_type text NOT NULL DEFAULT 'link' CHECK(menu_type IN ('link','category','page','custom')), open_new_tab boolean NOT NULL DEFAULT false, sort_order integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS settings (id serial PRIMARY KEY, key text NOT NULL UNIQUE, value text NOT NULL, description text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS gift_boxes (id serial PRIMARY KEY, name text NOT NULL, slug text UNIQUE NOT NULL, description text NOT NULL DEFAULT '', about_item text NOT NULL DEFAULT '', contents text NOT NULL DEFAULT '', personalisation text NOT NULL DEFAULT '', image text NOT NULL DEFAULT '', occasion text NOT NULL DEFAULT '', price numeric(12,2) NOT NULL DEFAULT 0 CHECK(price>=0), mrp numeric(12,2) NOT NULL DEFAULT 0 CHECK(mrp>=0), stock integer NOT NULL DEFAULT 0 CHECK(stock>=0), sku text NOT NULL DEFAULT '', weight_kg numeric(8,3) NOT NULL DEFAULT 0.5 CHECK(weight_kg>0), length_cm numeric(8,2) NOT NULL DEFAULT 20 CHECK(length_cm>0), breadth_cm numeric(8,2) NOT NULL DEFAULT 20 CHECK(breadth_cm>0), height_cm numeric(8,2) NOT NULL DEFAULT 10 CHECK(height_cm>0), seo_title text NOT NULL DEFAULT '', seo_description text NOT NULL DEFAULT '', sort_order integer NOT NULL DEFAULT 0, featured boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS content_sections (id serial PRIMARY KEY, key text NOT NULL UNIQUE, title text NOT NULL, subtitle text NOT NULL DEFAULT '', body text NOT NULL DEFAULT '', image text NOT NULL DEFAULT '', link text NOT NULL DEFAULT '/shop', button_text text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS payments (id bigserial PRIMARY KEY, order_id integer NOT NULL REFERENCES orders(id) ON DELETE CASCADE, provider text NOT NULL DEFAULT 'razorpay', provider_order_id text UNIQUE, provider_payment_id text UNIQUE, amount numeric(12,2) NOT NULL CHECK(amount>=0), currency text NOT NULL DEFAULT 'INR', status text NOT NULL DEFAULT 'created' CHECK(status IN ('created','authorized','captured','failed','refunded')), method text NOT NULL DEFAULT '', raw_response jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS shipments (id bigserial PRIMARY KEY, order_id integer NOT NULL UNIQUE REFERENCES orders(id) ON DELETE CASCADE, provider text NOT NULL DEFAULT 'shiprocket', provider_order_id text, shipment_id text, awb_code text NOT NULL DEFAULT '', courier_name text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'pending', label_url text NOT NULL DEFAULT '', tracking_url text NOT NULL DEFAULT '', courier_id text NOT NULL DEFAULT '', pickup_scheduled_at timestamptz, delivered_at timestamptz, booking_error text NOT NULL DEFAULT '', raw_response jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS integration_events (id bigserial PRIMARY KEY, provider text NOT NULL, event_type text NOT NULL, external_id text, payload jsonb NOT NULL DEFAULT '{}'::jsonb, processed boolean NOT NULL DEFAULT false, error text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id bigserial PRIMARY KEY, admin_id integer REFERENCES admins(id) ON DELETE SET NULL, action text NOT NULL, module text NOT NULL, record_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS orders_customer_idx ON orders(customer_id);
CREATE INDEX IF NOT EXISTS order_items_order_idx ON order_items(order_id);
CREATE INDEX IF NOT EXISTS products_category_idx ON products(category_id);
CREATE INDEX IF NOT EXISTS reviews_product_idx ON reviews(product_id);
CREATE TABLE IF NOT EXISTS customer_sessions (token_hash text PRIMARY KEY, customer_id integer NOT NULL REFERENCES customers(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS customer_otp_challenges (token_hash text PRIMARY KEY, phone text NOT NULL, attempts integer NOT NULL DEFAULT 0, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS auth_rate_limits (key text PRIMARY KEY, count integer NOT NULL, expires_at timestamptz NOT NULL);

CREATE INDEX IF NOT EXISTS payments_order_idx ON payments(order_id);
CREATE INDEX IF NOT EXISTS shipments_order_idx ON shipments(order_id);
CREATE INDEX IF NOT EXISTS integration_events_provider_idx ON integration_events(provider,created_at);
